#include "Stock.h"
#include "stock/stock_456.h"       // generated by reference/mtref --stock=456 --tables
#include "stock/stock_vintage.h"   //                              --stock=vintage
#include "stock/stock_budget.h"    //                              --stock=budget
#include "stock/pb_456.h"          // and their playback targets (--pbtables)
#include "stock/pb_vintage.h"
#include "stock/pb_budget.h"

#include <cmath>

namespace mt
{
// the three generated coatings share one grid (asserted), so one view type serves all
#define MT_COATING(S, P, NAME, ALIGNSP) \
    CoatingTables { NAME, S::FLUX_MR_NWBM, S::HB_OPERATING, S::HS_0VU, S::ALIGN_SPEED_CMS, \
                    S::SPEED_CMS, S::LAYER_FMAX, S::A_GRID, S::S_GRID, S::M_REM, \
                    S::ZONE_X_UM, S::ZONE_W_UM, S::ZONE_GAIN, S::G, P::SPEED_CMS, P::D_SPACING_UM, ALIGNSP }

static_assert (stock456::NV == STK_NV && stock456::NL == STK_NL && stock456::NA == STK_NA && stock456::NS == STK_NS && stock456::NM == STK_NM, "grid");
static_assert (stockvintage::NV == STK_NV && stockvintage::NL == STK_NL && stockvintage::NA == STK_NA && stockvintage::NS == STK_NS && stockvintage::NM == STK_NM, "grid");
static_assert (stockbudget::NV == STK_NV && stockbudget::NL == STK_NL && stockbudget::NA == STK_NA && stockbudget::NS == STK_NS && stockbudget::NM == STK_NM, "grid");
static_assert (pb456::NV == STK_NV && pbvintage::NV == STK_NV && pbbudget::NV == STK_NV, "grid");

const CoatingTables& coatingTables (int coating)
{
    // The surface spacing a fresh stock brings is aligned away by the record EQ, as
    // a technician trims record HF for the tape on the machine (shedding is not
    // re-aligned: it is the studio tape, decayed).
    static const CoatingTables C[NUM_COATINGS] = {
        MT_COATING (stock456,     pb456,     "studio (456 class)",            0.00),
        MT_COATING (stockvintage, pbvintage, "vintage low-output",            0.10),
        MT_COATING (stockbudget,  pbbudget,  "budget (echo-machine tape)",    0.15),
    };
    return C[(coating >= 0 && coating < NUM_COATINGS) ? coating : 0];
}

const StockMedium& stockMedium (int stock)
{
    // particle volume / packing: studio 0.28 x 0.045 um acicular at 40 % packing (a
    // 1970s high-output oxide); vintage 0.45 x 0.075 at 30 %; budget poorly dispersed,
    // so its particles act in small clusters (0.35 x 0.06, four at a time, 30 %);
    // shedding the studio particles with 12 % of them gone. docs/physics/09-stock.md
    // has the reasoning for every number.
    static const StockMedium M[NUM_STOCKS] = {
        //  name                coat pack  op     v/p       mod     rough  spc   drop/m depth hole  wear/pass fric
        { "STUDIO (456 class)",  0, 1.00, 250.0, 1.113e-3, 0.0025, 0.020, 0.00, 0.3, 0.8, 0.05, 2.0e-4, 1.0 },
        { "VINTAGE low-output",  1, 1.00, 185.0, 6.63e-3,  0.0060, 0.050, 0.10, 1.0, 1.2, 0.15, 5.0e-4, 1.3 },
        { "SHEDDING",            0, 0.88, 250.0, 1.265e-3, 0.0120, 0.150, 0.35, 6.0, 2.0, 0.50, 2.0e-3, 3.0 },
        { "BUDGET echo tape",    2, 1.00, 185.0, 1.32e-2,  0.0080, 0.070, 0.15, 2.0, 1.5, 0.20, 6.0e-4, 1.5 },
    };
    return M[(stock >= 0 && stock < NUM_STOCKS) ? stock : 0];
}

double valueNoise (double x, double lattice, uint64_t seed)
{
    // the interpolated value's variance, averaged over the step, is 0.7238: divide it out
    static const double norm = [] {
        double s = 0.0; const int n = 4096;
        for (int i = 0; i < n; ++i)
        {
            const double t = (i + 0.5) / n, t2 = t * t, t3 = t2 * t;
            const double w0 = -0.5 * t + t2 - 0.5 * t3, w1 = 1.0 - 2.5 * t2 + 1.5 * t3;
            const double w2 = 0.5 * t + 2.0 * t2 - 1.5 * t3, w3 = -0.5 * t2 + 0.5 * t3;
            s += w0 * w0 + w1 * w1 + w2 * w2 + w3 * w3;
        }
        return 1.0 / std::sqrt (s / n);
    }();
    const double y = x / lattice;
    const double fy = std::floor (y);
    const int64_t i = (int64_t) fy;
    const double t = y - fy, t2 = t * t, t3 = t2 * t;
    const uint64_t s = mix64 (seed * 0x632BE59BD9B4E019ull + 7);
    const double p0 = hashSym (mix64 ((uint64_t) (i - 1) ^ s)), p1 = hashSym (mix64 ((uint64_t) i ^ s));
    const double p2 = hashSym (mix64 ((uint64_t) (i + 1) ^ s)), p3 = hashSym (mix64 ((uint64_t) (i + 2) ^ s));
    const double v = p1 + 0.5 * t * (p2 - p0) + t2 * (p0 - 2.5 * p1 + 2.0 * p2 - 0.5 * p3) + t3 * (1.5 * (p1 - p2) + 0.5 * (p3 - p0));
    return v * norm;
}

} // namespace mt
